      role1 = 4103000,
      role2 = 403111,
      role3 = 403203,
      role5 = 4103401,
      sentence = "I thought back to the ID photo I saw earlier when searching for info: Crew cut, white shirt, black suit. Clean and presentable.",
      next = {15}
    },
