      beijing = 1261,
      dialog = 3,
      music = "11_Sorrow_LongEnding_Ver",
      renwu = "npc",
      role1 = 4103000,
      role2 = 403111,
      role3 = 403203,
      role5 = 4103401,
      sentence = "It turned out he was not working for a bank...",
