      music = "11_Sorrow_LongEnding_Ver",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4103000,
      role2 = 403110,
      role3 = 403203,
      role5 = 4103401,
      sentence = "Wendy never gave up on him, even during his incarceration.",
